records.command:
$env:PATH = 'C:/Users/offic/.cache/codex-runtimes/codex-primary-runtime/dependencies/native/git/cmd;' + $env:PATH
$env:GIT_TRACE2_EVENT = '0'
$taskReleaseSource = Join-Path (Get-Location).Path '.dip-local/release-0.3.12-final-source'
$taskReleaseZip = Join-Path (Get-Location).Path '.dip-local/release-0.3.12-final-source.zip'
$taskMeasuredArchive = Join-Path (Get-Location).Path '.dip-local/vxu-labs-dip-0.3.12-measured.tgz'
if (-not (Test-Path -LiteralPath $taskMeasuredArchive)) { Copy-Item -LiteralPath .dip-local/vxu-labs-dip-0.3.12.tgz -Destination $taskMeasuredArchive }
& 'C:/Users/offic/.cache/codex-runtimes/codex-primary-runtime/dependencies/native/git/cmd/git.exe' archive --format=zip --output=$taskReleaseZip HEAD
if ($LASTEXITCODE -ne 0) { throw 'Source archive failed' }
if (Test-Path -LiteralPath $taskReleaseSource) { throw 'Dedicated final source directory already exists; inspect before retry' }
Expand-Archive -LiteralPath $taskReleaseZip -DestinationPath $taskReleaseSource
Push-Location -LiteralPath $taskReleaseSource
try {
 npm.cmd ci --no-audit --no-fund
 if ($LASTEXITCODE -ne 0) { throw 'Clean dependencies failed' }
 npm.cmd run test:package
 if ($LASTEXITCODE -ne 0) { throw 'Final archive package smoke failed' }
 npm.cmd pack --ignore-scripts --pack-destination ..
 if ($LASTEXITCODE -ne 0) { throw 'Final package archive failed' }
} finally { Pop-Location }
